def is_Monotonic(A):
    if len(A) <= 1:
        return True
    increasing = all(A[i] <= A[i + 1] for i in range(len(A) - 1))
    decreasing = all(A[i] >= A[i + 1] for i in range(len(A) - 1))
    return increasing or decreasing

